-- Capital tab icon images generated for the four public navigation cards.
BEGIN;

CREATE TABLE IF NOT EXISTS public.capital_module_icon (
    module_key TEXT PRIMARY KEY CHECK (module_key IN ('poc', 'pilot', 'bank', 'invest')),
    png BYTEA NOT NULL CHECK (substring(png FROM 1 FOR 8) = decode('89504e470d0a1a0a', 'hex'))
);

INSERT INTO public.capital_module_icon (module_key, png)
VALUES
    ('poc', decode('', 'base64')),
    ('pilot', decode('', 'base64')),
    ('bank', decode('', 'base64')),
    ('invest', decode('', 'base64'))
ON CONFLICT (module_key) DO NOTHING;

COMMIT;
